THOUGHT: Now I have a better understanding of the issue. Looking at the test cases, I can see that in the `formatTexts` function in `completion.go`, there's a potential issue with width calculation when text is truncated.

Let me analyze the problematic part of the code more carefully:

In the `formatTexts` function:
```go
} else if x > width {
    x := runewidth.Truncate(o[i], width, shortenSuffix)
    // When calling runewidth.Truncate("您好xxx您好xxx", 11, "...") returns "您好xxx..."
    // But the length of this result is 10. So we need fill right using runewidth.FillRight.
    n[i] = prefix + runewidth.FillRight(x, width) + suffix
}
```

The issue is that `runewidth.Truncate` might return a string whose visual width is less than the specified width due to the way the truncation works with the suffix. Then `runewidth.FillRight` is used to pad it to the correct width, but there might be an off-by-one error in the width calculation.

Let me create a simple test script to reproduce the issue:

```bash
cat <<'EOF' > reproduce_issue.go
package main

import (
	"fmt"
	runewidth "github.com/mattn/go-runewidth"
)

const shortenSuffix = "..."

func main() {
	// Example from the issue description
	suggestions := []string{"This is a long suggestion", "Another long suggestion", "Yet another long one"}

	maxWidth := 10 // Small width to force truncation

	lenPrefix := 1 // Single space prefix
	lenSuffix := 1 // Single space suffix
	lenShorten := runewidth.StringWidth(shortenSuffix)

	fmt.Printf("lenPrefix: %d, lenSuffix: %d, lenShorten: %d\n", lenPrefix, lenSuffix, lenShorten)

	min := lenPrefix + lenSuffix + lenShorten
	fmt.Printf("min required width: %d\n", min)

	if min >= maxWidth {
		fmt.Println("Not enough space to display anything meaningful")
		return
	}

	availableWidth := maxWidth - lenPrefix - lenSuffix
	fmt.Printf("Available width for text: %d\n", availableWidth)

	for i, suggestion := range suggestions {
		originalWidth := runewidth.StringWidth(suggestion)
		fmt.Printf("\nSuggestion %d: '%s' (width: %d)\n", i, suggestion, originalWidth)

		if originalWidth <= availableWidth {
			// No truncation needed
			spaces := ""
			for j := 0; j < availableWidth-originalWidth; j++ {
				spaces += " "
			}
			result := " " + suggestion + spaces + " "
			fmt.Printf("No truncation: '%s' (width: %d)\n", result, runewidth.StringWidth(result))
		} else {
			// Truncation needed
			truncated := runewidth.Truncate(suggestion, availableWidth, shortenSuffix)
			truncatedWidth := runewidth.StringWidth(truncated)
			fmt.Printf("Truncated: '%s' (width: %d)\n", truncated, truncatedWidth)

			filled := runewidth.FillRight(truncated, availableWidth)
			filledWidth := runewidth.StringWidth(filled)
			fmt.Printf("Filled: '%s' (width: %d)\n", filled, filledWidth)

			result := " " + filled + " "
			fmt.Printf("Final result: '%s' (width: %d)\n", result, runewidth.StringWidth(result))
		}
	}
}
EOF
```

